import {productFactsFixtureHtml} from './bookingProductFactsPage';
export function guardedCalendarFixture(mode='normal'){
 const label1='2027年1月15日金曜日, チェックイン日',label2=mode==='duplicate-role'?'2027年1月16日土曜日, チェックイン日':'2027年1月16日土曜日, チェックアウト日';
 const network=mode.startsWith('http-')?`if(!open)void fetch('/forbidden',{method:'${mode.slice(5)}'}).catch(()=>{});`:mode==='close-http'?`if(open)void fetch('/forbidden',{method:'POST',body:'synthetic'}).catch(()=>{});`:'';
 const mutation=mode==='table-opacity-change'?"if(!open)document.querySelector('#hprt-table').style.opacity='0';":mode==='table-aria-hide'?"if(!open)document.querySelector('#hprt-table').setAttribute('aria-hidden','true');":mode==='quantity-change'?"if(!open)document.querySelector('#hprt-table select').value='1';":mode==='price-change'?"if(!open){document.querySelector('#hprt-table .prco-wrapper').textContent='￥22,000';document.querySelector('#hprt-table select').options[1].textContent='1 (￥22,000)';}":'';
 const header=`<div id='hp_availability_style_changes'><button type='button' data-testid='searchbox-dates-container' aria-expanded='false' onclick="const open=this.getAttribute('aria-expanded')==='true';this.setAttribute('aria-expanded',open?'false':'true');document.getElementById('selected-calendar').hidden=open;document.documentElement.dataset.dateClicks=String(Number(document.documentElement.dataset.dateClicks||0)+1);${network}${mutation}">日付を選択\n<span data-testid='date-display-field-start'>1月15日(金)</span> — <span data-testid='date-display-field-end'>1月16日(土)</span></button><button aria-label='宿泊人数と部屋数。選択済みの内容：大人2名 · 子供0名 · 1部屋'>Party</button>
 <div id='selected-calendar' data-testid='searchbox-datepicker-calendar' hidden><h3 id='bui-calendar-month-2027-01'>${mode==='wrong-heading'?'2028年1月':'2027年1月'}</h3><table role='grid' aria-labelledby='bui-calendar-month-2027-01'><tr><td role='gridcell' aria-selected='true' aria-label='${label1}'><span data-date='2027-01-15' aria-label='${label1}'>15</span></td><td role='gridcell' aria-selected='true' aria-label='${label2}'><span data-date='2027-01-16' aria-label='${label2}'>16</span></td></tr></table></div></div>`;
 const html=productFactsFixtureHtml().replace(/<div id='hp_availability_style_changes'>[\s\S]*?<\/div>/u,header);return mode==='same-weekday-other-year'?html.replaceAll('2027','2021'):html;
}
